import json, csv, re
from pathlib import Path
from collections import Counter

ROOT=Path('/workspace/scratch/34467c98be4a/GY1987_work')
OUT=ROOT/'shards'
talks=[]; items=[]; problems=[]; corrections=[]; areas={}

def talk(record,date,speaker,pages,title,summary):
    title=title.replace('\textquotesingle s',"'s").replace('\\textquotesingle s',"'s").replace('Kn\\\"orrer','Knörrer')
    talks.append(dict(record=record,date=date,speaker=speaker,pages=pages,title=title,kind='talk',summary=summary))

def item(record,pages,kind,title,notes,statement,fate,status,refs=(),reconstruction='',cl='E',literal='correct',match='exact',verification='read the result',development='none',confidence='high',speaker=None,area=''):
    title=title.replace('\textquotesingle s',"'s").replace('\\textquotesingle s',"'s").replace('Kn\\\"orrer','Knörrer')
    n=1+sum(x['record']==record for x in items)
    d=dict(id=f'1987-{record}.{n}',record=record,pages=pages,kind=kind,title=title,notes=notes,statement=statement,reconstruction=reconstruction,**{'class':cl},fate=fate,present_status='As of 11 November 2026, '+status,literal_correctness=literal,publication_match=match,verification=verification,development=development,problem='',worth='',refs=list(refs),confidence=confidence)
    if speaker:d['speaker']=speaker
    items.append(d); areas[d['id']]=area
    return d

def corr(page,place,reads,should,evidence,applies='both',typ='faithful_error'):
    corrections.append(dict(page=page,place=place,transcription_reads=reads,should_read=should,evidence=evidence,applies_to=applies,type=typ))

def checkpoint():
    for obj in talks+items+problems:
        for key,val in obj.items():
            if isinstance(val,str):obj[key]=val.replace('\textquotesingle',r'\textquotesingle')
    for name,obj in [('talks',talks),('items',items),('problems',problems),('areas',areas)]:
        (OUT/f'early_{name}.json').write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')
    with (OUT/'early_corrections.csv').open('w',newline='') as f:
        w=csv.DictWriter(f,fieldnames=['page','place','transcription_reads','should_read','evidence','applies_to','type']);w.writeheader();w.writerows(corrections)

S='stacks2026foundations'; G='grothendieck1957homological'; H='hartshorne1966residues'; M='macdonald1995symmetric'; B='bernsteingelfandgelfand1973schubert'; K='kerov1987realizations'

talk(714,'1987-10-05','A. A. Beilinson','P001385-P001388','Sheaf cohomology and the preparation for Verdier duality',r'Following the previous notebook\textquotesingle s discussion of sheaves, Beilinson develops sheafification, exactness, flabby resolutions, and cohomology. A finite-poset exercise connects the general formalism with combinatorial sheaves; the last page begins the compact-support dual construction needed for Verdier duality. These are foundational results, with hypotheses suppressed in several classroom formulations.')
item(714,'P001385-P001386','theorem','The abelian category of sheaves',r'Kernels are defined sectionwise and cokernels by associating a sheaf to the sectionwise cokernel; Exercise 2 identifies kernel of the cokernel with cokernel of the kernel.',r'For a topological space \(X\), sheaves of complex vector spaces form an abelian category. For \(f:\mathcal F\to\mathcal G\), \((\ker f)(U)=\ker(\mathcal F(U)\to\mathcal G(U))\), while \(\operatorname{coker}f\) is the sheafification of the sectionwise cokernel; \(\operatorname{coim}f\simeq\operatorname{im}f\).',r'This is pre-seminar sheaf homological algebra; see \citet[\S 3]{grothendieck1957homological} and the modern sheafification construction in \citet[Tag 007X]{stacks2026foundations}.','this remains the standard abelian-category structure; the sectionwise cokernel need not itself be a sheaf.',[G,S],area='Sheaves and homological algebra')
item(714,'P001385-P001386','construction','Sheafification and its universal property',r'The notes glue compatible local representatives, denote the associated sheaf by \(C^+\), and require unique factorization of every map from \(C\) to a sheaf.',r'For every presheaf \(C\) of complex vector spaces there is a sheaf \(aC\) and a map \(C\to aC\) such that \(\operatorname{Hom}(aC,\mathcal F)\cong\operatorname{Hom}(C,\mathcal F)\) naturally for every sheaf \(\mathcal F\); \(C_x\to(aC)_x\) is an isomorphism for every \(x\).',r'\citet[Lemmas 6.17.1--6.17.2 and the following universal property, Tag 007X]{stacks2026foundations} gives the construction. The notation \(C^+\) here names the completed associated sheaf, not necessarily one application of the usual plus construction.','the universal property uniquely determines sheafification up to unique isomorphism.',[S],reconstruction=r'The stalk formulation disambiguates the abbreviated gluing description; a single compatible-family plus construction requires a separated input, or a second application.',literal='correct with missing hypotheses',area='Sheaves and homological algebra')
item(714,'P001386','theorem','Exactness is tested on stalks',r'Exercise 3 says a sequence of sheaves is exact if and only if all its stalk sequences are exact.',r'A sequence \(\mathcal F_1\to\mathcal F_2\to\mathcal F_3\) of sheaves of vector spaces on \(X\) is exact at \(\mathcal F_2\) if and only if \((\mathcal F_1)_x\to(\mathcal F_2)_x\to(\mathcal F_3)_x\) is exact for every \(x\in X\).',r'Sheafification preserves stalks, and filtered colimits of vector spaces are exact; this is part of the classical sheaf formalism of \citet[\S 3]{grothendieck1957homological}.','the statement holds without separation or local-compactness assumptions on the space.',[G,S],area='Sheaves and homological algebra')
item(714,'P001386','definition','Flabby sheaves and the local-system caveat',r'A sheaf is called flabby when every section on an open subset extends to all of \(X\). The following sentence says that locally constant sheaves are not flabby.',r'\(\mathcal F\) is flabby if \(\mathcal F(X)\to\mathcal F(U)\) is surjective for every open \(U\subset X\), equivalently all open restriction maps are surjective. A nonzero constant sheaf on a connected locally connected space with a disconnected open subset is not flabby. The zero sheaf and every sheaf on a discrete space give exceptions to a blanket claim about local systems.',r'The definition and acyclicity are classical; \citet[Definition 20.12.1 and Lemma 20.12.3, Tag 09SV]{stacks2026foundations}. The exceptions follow directly from the definition.','the definition is correct, but the unqualified assertion about locally constant sheaves is false.',[S],reconstruction='The extra topological and nonzero hypotheses state the situation illustrated by the notebook drawing.',literal='false as written',area='Sheaves and homological algebra')
item(714,'P001386-P001387','problem','Sheaves and flabby sheaves on a finite poset',r'Problem 4 equips a finite poset \(P\) with \(\overline{\{x\}}=\{y:y\le x\}\), asks for sheaves as representations, and asks which are flabby.',r'With upper sets open, a sheaf on finite \(P\) is equivalently a covariant functor \(F:P\to\operatorname{Vect}_{\mathbb C}\). Its sections on an upper set \(U\) are \(\varprojlim_{x\in U}F(x)\). It is flabby exactly when \(F(x)\to\varprojlim_{y>x}F(y)\) is surjective for every \(x\in P\), with the empty limit zero.',r'The diagram description is elementary sheaf theory; the stated flabbiness test is reconstructed directly: extend a compatible section over an upper set by adding its remaining points in reverse order. Necessity follows by restricting from \(\{y:y\ge x\}\) to \(\{y:y>x\}\). Compare the definition in \citet[Tag 09SV]{stacks2026foundations}.','the exercise has this finite and effective answer; surjectivity on individual comparable pairs alone is insufficient at branching points.',[S],reconstruction='The inverse-limit criterion and its two-direction argument are our explicit solution of the recorded exercise.',match='partial',development='annotated',area='Sheaves and homological algebra')
item(714,'P001387','claim','Combinatorial sheaves and the poset of strata',r'The map sending a point to its stratum is said to induce an equivalence from sheaves on the poset of strata to combinatorial sheaves on \(X\).',r'For a finite regular cell complex with its face poset, cellular sheaves can be encoded by vector spaces on cells and compatible maps along face inclusions. For an arbitrary stratification the stated equivalence requires additional hypotheses: its exact truth depends on what is meant here by a combinatorial sheaf and on incidence and monodromy data.',r'The finite-poset assertion is precise, but the notes refer back to definitions in a previous notebook. The present pages do not provide the assumptions needed to identify the claimed equivalence for all stratifications; the general sheaf formalism in \citet[\S 3]{grothendieck1957homological} does not supply them automatically.','a standard cellular interpretation is available, while the unrestricted stratified-space claim cannot be certified from this record alone.',[G],reconstruction='The regular-cell formulation is a limited modern interpretation, not a claim that the notebook imposed that condition.',literal='not determinable',match='partial',verification='indirect',confidence='medium',area='Sheaves and homological algebra')
item(714,'P001387','theorem','Exactness of sections when the kernel is flabby',r'The left-exact global-section functor becomes exact on a short exact sequence when its first term is flabby.',r'If \(0\to\mathcal F\to\mathcal G\to\mathcal H\to0\) is exact and \(\mathcal F\) is flabby, then \(0\to\Gamma(X,\mathcal F)\to\Gamma(X,\mathcal G)\to\Gamma(X,\mathcal H)\to0\) is exact.',r'\citet[Lemma 20.12.3 and its proof, Tag 09SV]{stacks2026foundations} proves precisely the needed lifting property. It belongs to the older flabby-resolution method.','the assertion is valid on every topological space.',[S],area='Sheaves and homological algebra')
item(714,'P001387-P001388','construction','Flabby resolutions and sheaf cohomology',r'Every sheaf embeds in a flabby one; iterating on cokernels gives a resolution, and its global-section cohomology is independent of the resolution.',r'For every sheaf \(\mathcal F\), the map into the sheaf \(U\mapsto\prod_{x\in U}\mathcal F_x\) is injective and the target is flabby. Iteration gives \(0\to\mathcal F\to I^0\to I^1\to\cdots\). The groups \(H^i(\Gamma(X,I^\bullet))\) are independent of a chosen flabby resolution and equal \(R^i\Gamma(X,\mathcal F)\).',r'\citet[\S 3]{grothendieck1957homological} supplies the derived-functor framework; flabby acyclicity is checked in \citet[Lemma 20.12.3, Tag 09SV]{stacks2026foundations}. This is exposition, not a new 1987 construction.','the resolution computes sheaf cohomology in all nonnegative degrees.',[G,S],reconstruction='The product-of-stalks construction makes the asserted embedding explicit; independence is via the acyclic-resolution comparison theorem.',area='Sheaves and homological algebra')
item(714,'P001388','construction','Cohomology with compact supports',r'The same resolution construction is proposed with compactly supported sections on a locally compact space.',r'For a locally compact Hausdorff space \(X\), \(\Gamma_c(X,\mathcal F)\) consists of sections with compact support, and \(H_c^i(X,\mathcal F)=R^i\Gamma_c(X,\mathcal F)\). A resolution by \(c\)-soft sheaves, in particular an appropriate flabby resolution, computes these groups.',r'This is the standard compact-support construction underlying the duality formalism already presented in \citet[Chapters II--III]{hartshorne1966residues}; only the publisher chapter metadata was reopened for that older volume.','the locally compact Hausdorff setting gives the usual compact-support theory; unrestricted support claims require a specified family of supports.',[H],reconstruction='Hausdorffness and the acyclicity condition are supplied explicitly.',literal='correct with missing hypotheses',verification='publisher metadata checked',match='partial',area='Sheaves and homological algebra')
item(714,'P001388','construction','The dual of compactly supported sections',r'The last construction sets \(\mathcal F^*(V)=\Gamma_c(V,\mathcal F)^*\), with restrictions dual to extension by zero, and relates it to flabbiness.',r'For sheaves of complex vector spaces on locally compact Hausdorff \(X\), set \(D_c\mathcal F(U)=\operatorname{Hom}_{\mathbb C}(\Gamma_c(U,\mathcal F),\mathbb C)\). If \(\mathcal F\) is \(c\)-soft, compact-support Mayer--Vietoris makes this presheaf a sheaf. Its restriction maps are surjective because linear functionals extend from vector subspaces, so it is flabby.',r'This is the elementary compact-support dual used in derived duality; compare the 1966 duality framework \citep[Chapters II--III]{hartshorne1966residues}. It is not an assertion that naive pointwise dualization of an arbitrary sheaf is Verdier duality.','the construction is valid under the stated acyclicity condition; derived duality requires applying it to a suitable complex.',[H],reconstruction='The sufficient c-soft hypothesis and the Mayer--Vietoris explanation specify the missing sheaf condition.',literal='correct with missing hypotheses',verification='indirect',match='partial',area='Sheaves and homological algebra')
corr('P001386','sentence following flabby-sheaf definition','Locally constant sheaves are not flabby','The displayed example obstructs flabbiness only with additional hypotheses; zero sheaves and sheaves on discrete spaces are flabby.','The Russian text and scan make the unrestricted assertion. The counterexamples follow immediately from the definition.')
checkpoint()

talk(715,'1987-10-12','I. M. Gelfand','P001389-P001390','Dyson\textquotesingle s constant term and Good\textquotesingle s proof',r'Gelfand presents the Dyson constant-term identity and the short interpolation proof attributed in the notebook to a name written as \ru{Вуда}. The exact recurrence and bibliographic year identify I. J. Good\textquotesingle s 1970 proof. The final induction ends at the top of P001390, before Veselov\textquotesingle s heading.')
item(715,'P001389-P001390','theorem','Dyson\textquotesingle s constant-term identity',r'For nonnegative integral \(a_j\), the constant term of \(F(x;a)=\prod_{i\ne j}(1-x_j/x_i)^{a_j}\) is asserted to be \((\sum a_j)!/\prod a_j!\).',r'For every \(n\ge1\) and \(a\in\mathbb Z_{\ge0}^n\), \[\operatorname{CT}_{x_1,\ldots,x_n}\prod_{i\ne j}(1-x_j/x_i)^{a_j}=\frac{(a_1+\cdots+a_n)!}{a_1!\cdots a_n!}.\]',r'\citet[p.~1884]{good1970short} states this exact identity and records the 1962 proofs by Gunson and Wilson; Good\textquotesingle s paper was received 26 December 1969 and published June 1970.','the identity is an established theorem, and the seminar occurrence is expository.', ['good1970short'],area='Algebraic combinatorics')
item(715,'P001389-P001390','method','Good\textquotesingle s interpolation recurrence',r'Interpolation is applied to a function printed as identically zero, but the ensuing sum is one and is used to reduce the exponents one at a time.',r'For distinct nonzero \(x_i\), interpolation of \(1\) gives \(\sum_j\prod_{i\ne j}(1-x_j/x_i)^{-1}=1\). Thus the constant terms satisfy \(G(a)=\sum_jG(a-e_j)\) if all \(a_j>0\), the deletion rule when \(a_j=0\), and \(G(0)=1\). These rules uniquely determine the multinomial coefficient.',r'The complete proof is \citet[p.~1884, equations (1)--(3)]{good1970short}. The source explicitly interpolates the constant function one.','the proof works after correcting that constant; no limiting interpretation of a zero exponent is needed.', ['good1970short'],literal='false as written',development='annotated',area='Algebraic combinatorics')
corr('P001389','interpolation substitution','f(x) identically 0','f(x) identically 1','The scan supports the recorded zero; Good 1970 p.1884 explicitly interpolates the function one, and only that gives the displayed identity.')
corr('P001389','1970 proof attribution','Vuda / Вуда','I. J. Good (Гуд); retain the handwritten form in the diplomatic source','Good 1970 reproduces the exact interpolation and recurrence. This is a bibliographic emendation, not an asserted palaeographic rereading.',typ='provenance')
checkpoint()

talk(716,'1987-10-12','A. P. Veselov','P001390-P001391','Quadrics, the Neumann system, and two Poisson brackets',r'Veselov compares geodesics on a quadric with the Neumann oscillator on a sphere using Kn\"orrer\textquotesingle s time change and Gauss map. He then presents a spectral-operator interpretation and two Hamiltonian descriptions in dimension three. Gelfand asks an inverse problem for a rank-one matrix perturbation; its uniqueness needs qualifications absent from the shorthand question.')
item(716,'P001390','theorem','Geodesics and the constrained Neumann equation',r'The two columns write \(\ddot q=\lambda Aq\) on \((Aq,q)=1\), and \(x^{\prime\prime}=-Ax+ux\) on \(|x|^2=1\).',r'Let \(A\) be positive definite symmetric. A geodesic \(q(s)\) on \(q^TAq=1\), in arclength, satisfies \(q_{ss}=\lambda Aq\), where \(\lambda=-q_s^TAq_s/\|Aq\|^2\). Motion on the unit sphere in potential \(x^TAx/2\) satisfies \(x^{\prime\prime}=-Ax+ux\), with \(u=x^TAx-\|x^{\prime}\|^2\).',r'These constrained equations are classical. The derivation and normalization are reproduced by \citet[\S\S 2--4]{veselovwu2020geodesic}, whose later work explicitly distinguishes Kn\"orrer\textquotesingle s 1982 theorem from its own hyperboloid scattering results.','both equations follow directly by differentiating their constraints.', ['veselovwu2020geodesic'],reconstruction='Positive definiteness and arclength fix the ellipsoid case and the signs of the multipliers.',literal='correct with missing hypotheses',area='Integrable systems')
item(716,'P001390','theorem','Kn\"orrer\textquotesingle s Gauss-map correspondence',r'The notes credit H. Kn\"orrer, 1982: after changing the parameter, \(x=Aq/|Aq|\) takes geodesics into Neumann trajectories.',r'For a nonconstant ellipsoid geodesic as above, choose \(d\tau/ds=\sqrt{-\lambda(s)}\). Then \(x(\tau)=Aq(\tau)/\|Aq(\tau)\|\) satisfies the Neumann equation with matrix \(A\). The image is a fixed level of an additional Neumann integral; it is not all Neumann trajectories for the one fixed quadric.',r'\citet[Theorem 4.1, equations (28)--(33)]{veselovwu2020geodesic} gives the calculation and explicitly attributes it to Kn\"orrer 1982. The original DOI was located but the original full paper could not be opened.','the forward correspondence is established; the extra integral matters for a converse.', ['veselovwu2020geodesic','knorrer1982geodesics'],reconstruction='The explicit time change and restriction on the converse are supplied from the primary later calculation.',literal='correct with missing hypotheses',area='Integrable systems')
item(716,'P001390-P001391','construction','The scalar spectral operator and its gauge transform',r'Each coordinate is an eigenfunction of \(L=-d^2/dt^2+u\); a first-derivative operator \(\widetilde L=-d^2/dt^2+v\,d/dt\) is called conjugate to it by the Gauss or Miura substitution.',r'If \(x_i^{\prime\prime}=-a_ix_i+ux_i\), then \(Lx_i=a_ix_i\). For \(r>0\) with \(v=2r^{\prime}/r\), \[r^{-1}(-D^2+vD)r=-D^2+\frac{v^2}{4}-\frac{v^{\prime}}2.\] In the Gauss substitution take \(r=\|Aq\|\), so constant multiplication by \(A\) commutes with these scalar operators.',r'The first identity is immediate from the differential equation. The gauge calculation is independently expanded here; it agrees with the time-change calculation in \citet[\S 4]{veselovwu2020geodesic}.','this is an operator conjugacy on any interval where the multiplier is nonzero, not a global spectral assertion without boundary conditions.', ['veselovwu2020geodesic'],reconstruction='The gauge multiplier, potential, interval, and absence of an imposed operator domain are made explicit.',literal='correct with missing hypotheses',match='partial',development='annotated',area='Integrable systems')
item(716,'P001391','problem','Recovering a rank-one perturbation from its spectrum',r'Gelfand fixes a symmetric matrix \(A\), gives the eigenvalues of \(A+K\) with \(\operatorname{rank}K=1\), and asks how to recover \(K\).',r'For \(A=\operatorname{diag}(\alpha_1,\ldots,\alpha_n)\) with distinct real entries and symmetric positive rank-one \(K=vv^T\), a prescribed characteristic polynomial \(p_\beta(z)=\prod_j(z-\beta_j)\) requires \[v_i^2=-\frac{p_\beta(\alpha_i)}{\prod_{k\ne i}(\alpha_i-\alpha_k)}.\] Nonnegative right sides, with at least one strictly positive, are necessary and sufficient for rank exactly one. The signs of nonzero \(v_i\), modulo a common sign, remain undetermined. For arbitrary \(K=uv^T\), only the products \(u_iv_i\) are recovered.',r'The matrix determinant lemma yields \(p_\beta(z)/p_\alpha(z)=1-\sum_i v_i^2/(z-\alpha_i)\); taking residues proves the formula. This is a classical rank-one secular equation, related to the spectral viewpoint in \citet[\S 2]{veselovwu2020geodesic}, but the notebook\textquotesingle s bare reconstruction question is not uniquely solvable.', 'the normalized symmetric inverse problem is explicit; uniqueness of the matrix in a fixed basis is false without extra data.', ['veselovwu2020geodesic'],reconstruction='Simple spectrum, positivity, and the distinction between a matrix and its diagonal-sign-conjugacy class are additional assumptions; the residue argument is our verification.',literal='correct with missing hypotheses',match='partial',verification='indirect',development='annotated',speaker='I. M. Gelfand',area='Linear algebra and inverse problems')
item(716,'P001391','claim','The Euclidean Lie--Poisson realization of Neumann motion',r'The notes set \(M=[\dot x,x]\), \(p=x\), use the standard \(e(3)\) brackets, and take \(H=(M^2+(Ap,p))/2\).',r'With \(\varepsilon_{123}=1\), brackets \(\{M_i,M_j\}=\varepsilon_{ijk}M_k\), \(\{M_i,p_j\}=\varepsilon_{ijk}p_k\), \(\{p_i,p_j\}=0\), and convention \(\dot f=\{f,H\}\), the Hamiltonian gives \(\dot p=M\times p\) and \(\dot M=(Ap)\times p\). On \(p^2=1\), \(M\cdot p=0\), one has \(M=p\times\dot p\) and \(\ddot p=-Ap+(p^TAp-\dot p^2)p\).',r'The equations are verified by contracting the displayed brackets; the Neumann normalization agrees with \citet[\S 3]{veselovwu2020geodesic}. The handwritten \([\dot x,x]\) has the opposite sign under the usual cross-product convention.','the Hamiltonian realization is standard, with the momentum sign corrected or an opposite cross-product convention declared.', ['veselovwu2020geodesic'],reconstruction='Orientation and Hamiltonian-vector-field conventions are specified to make the sign comparison meaningful.',literal='false as written',match='partial',development='annotated',area='Integrable systems')
item(716,'P001391','claim','The second bracket fails Jacobi as written',r'The second table reads \(\{M_i,M_j\}_2=\varepsilon_{ijk}a_kM_k\), \(\{M_i,p_j\}_2=\varepsilon_{ijk}a_kp_k\), \(\{p_i,p_j\}_2=\varepsilon_{ijk}M_k\), with \(F=p^2/2\). It is said to give another Hamiltonian description.',r'The displayed table is not a Poisson bracket for a general diagonal \(A\): its Jacobiator on \((M_1,p_1,p_2)\) is \((a_3-a_2)M_2\). Its formal vector field for \(F=p^2/2\) is also the negative of the first recorded flow. One algebraically valid repair keeps \(\{M_i,M_j\}_2=\varepsilon_{ijk}a_kM_k\), changes \(\{M_i,p_j\}_2\) to \(\varepsilon_{ijk}a_jp_k\), and changes \(\{p_i,p_j\}_2\) to \(-\varepsilon_{ijk}M_k\). This repaired bracket is Poisson and gives \(\dot M=Ap\times p,\ \dot p=M\times p\) with the same \(F\).',r'The scan confirms the literal indices and sign. The Jacobi counterexample, all coordinate Jacobi identities for the repaired table, and the two Hamiltonian vector fields are independently calculated in the accompanying script. The underlying Neumann system is classical \citep[\S 3]{veselovwu2020geodesic}; that citation is not an exact source for this chosen repair. The independent associative-matrix construction in Section~\ref{dev:poisson-repair} proves Jacobi and compatibility for the repair.','the literal second Hamiltonian description is false; the displayed repair is a verified reconstruction, not a uniquely established reading of the intended historical formula.', ['veselovwu2020geodesic'],reconstruction='The mixed coefficient and the momentum-momentum sign are changed explicitly; simply reversing time does not cure the failed Jacobi identity.',literal='false as written',match='partial',verification='indirect',development='annotated',area='Integrable systems')
corr('P001391','definition of angular momentum','M=[xdot,x] with the displayed standard brackets and dot f={f,H}','M=[x,xdot], or explicitly reverse the cross-product convention','Direct epsilon contraction gives pdot=M cross p; on p squared=1 and M dot p=0 this forces M=p cross pdot. The scan and Russian transcription agree.')
corr('P001391','second bracket and Hamiltonian','Mixed bracket epsilon_ijk a_k p_k and momentum bracket epsilon_ijk M_k; F=p squared/2','The table fails Jacobi. One verified repair uses epsilon_ijk a_j p_k and -epsilon_ijk M_k, keeping F=p squared/2','The scan confirms both literal entries. Jacobi(M1,p1,p2)=(a3-a2)M2. Exact symbolic checks show the repaired table is Poisson and produces the first Neumann vector field; the repair is a reconstruction, not a claimed unique intention.')
checkpoint()

talk(717,'1987-10-12','A. A. Beilinson','P001392-P001394','Complexes, homotopy, and localization',r'Beilinson moves from poset representations to complexes over an abelian category, homotopies, and quasi-isomorphisms. Roof diagrams and the Ore construction introduce the derived category. The same localization is revisited on 23 November; these occurrences are kept separate, with a cross-link rather than treated as new research.')
item(717,'P001392','definition','Combinatorial sheaves as representations, recalled',r'The opening reminder assigns objects to points of a poset and compatible morphisms to ordered pairs.',r'A representation of a poset \(P\) in an abelian category \(\mathcal A\) is a family \(F_x\) with maps \(f_{xy}:F_x\to F_y\) for \(x\le y\), satisfying \(f_{xx}=1\) and \(f_{yz}f_{xy}=f_{xz}\). For finite \(P\) with upper-set topology this is the corresponding cellular sheaf diagram.',r'This repeats the finite-poset construction in occurrence 1987-714.5; its elementary sheaf interpretation uses the same restriction and gluing axioms \citep[Tag 007X]{stacks2026foundations}.','this is an established categorical encoding, with the direction fixed by the notebook\textquotesingle s topology.',[S],area='Sheaves and homological algebra')
item(717,'P001392-P001393','definition','The abelian category of complexes and cohomology',r'The notes introduce \(C(\mathcal A)\), bounded variants, differentials, morphisms, and \(H^i\).',r'For an abelian category \(\mathcal A\), \(C(\mathcal A)\) has cochain complexes \((X^i,d^i)\), \(d^{i+1}d^i=0\), and degree-preserving chain maps. It is abelian with kernels and cokernels degreewise, and \(H^i(X)=\ker d^i/\operatorname{im}d^{i-1}\). The subcategories \(C^b,C^+,C^-\) impose bounded, bounded-below, or bounded-above terms.',r'This predates the seminar; the derived-category account was already published in \citet[Chapter I]{hartshorne1966residues}. Modern definitions and cohomology are in \citet[Chapters 12--13]{stacks2026foundations}.','these are standard definitions; cohomology need not be exact as a functor on complexes.',[H,S],area='Sheaves and homological algebra')
item(717,'P001393','construction','Homotopy and the quotient category',r'A null homotopy is written \(f=d\psi+\psi d\); quotienting by such maps defines \(K(\mathcal A)\).',r'Chain maps \(f,g:X\to Y\) are homotopic if \(f^i-g^i=d_Y^{i-1}h^i+h^{i+1}d_X^i\) for maps \(h^i:X^i\to Y^{i-1}\). Null-homotopic maps form an additive two-sided ideal. The quotient \(K(\mathcal A)\) has the same objects as \(C(\mathcal A)\), and every \(H^i\) factors through it.',r'\citet[\S 13.8 and \S 13.11, Tag 05RR]{stacks2026foundations} gives precisely this construction; its pre-1987 setting is \citet[Chapter I]{hartshorne1966residues}.','homotopy is weaker than isomorphism of complexes and stronger than the derived equivalence generated by quasi-isomorphisms.',[S,H],area='Sheaves and homological algebra')
item(717,'P001393-P001394','definition','Quasi-isomorphisms',r'A map inducing isomorphisms in all cohomological degrees is called a quasi-isomorphism.',r'A chain map \(f:X\to Y\) is a quasi-isomorphism if \(H^i(f)\) is an isomorphism for every integer \(i\). Such maps need not be homotopy equivalences in an arbitrary abelian category.',r'\citet[\S 13.11, Lemma 13.11.2]{stacks2026foundations} identifies precisely this multiplicative system, in the classical derived-category construction.','the distinction from homotopy equivalence is essential and remains unchanged.',[S,H],area='Sheaves and homological algebra')
item(717,'P001394','theorem','The Ore construction for a roof',r'A roof with a quasi-isomorphism on one leg can be replaced by a common outgoing diagram; the construction is used to compose fractions.',r'If \(s:Z\to X\) is a quasi-isomorphism and \(f:Z\to Y\) is a chain map, the homotopy pushout \(P=\operatorname{Cone}((s,-f):Z\to X\oplus Y)\) admits maps \(X\to P\), \(Y\to P\) commuting in \(K(\mathcal A)\), and \(Y\to P\) is a quasi-isomorphism. The dual statement uses a homotopy pullback.',r'This is the calculus of quasi-isomorphisms underlying \citet[Lemma 13.11.2 and \S 13.5]{stacks2026foundations}; the cone construction is classical \citep[Chapter I]{hartshorne1966residues}.','the outgoing quasi-isomorphism is on the opposite leg; commutativity is in the homotopy category.',[S,H],reconstruction='The explicit cone and the location of the outgoing quasi-isomorphism make the diagrammatic lemma precise.',area='Sheaves and homological algebra')
item(717,'P001394','construction','The derived category as roofs',r'Morphisms are roofs \(X\leftarrow Z\to Y\), the left map a quasi-isomorphism, modulo common refinement.',r'For an essentially small abelian category, \(D(\mathcal A)=K(\mathcal A)[\mathrm{Qis}^{-1}]\). A morphism is represented by \(X\xleftarrow{s}Z\xrightarrow{f}Y\) with \(s\) a quasi-isomorphism. Equivalent roofs have common refinements in \(K(\mathcal A)\); composition is obtained by an Ore square. The localization is universal among functors inverting quasi-isomorphisms.',r'\citet[Definition 13.11.3, Tag 05RR]{stacks2026foundations}; the foundational account appears in \citet[Chapter I]{hartshorne1966residues}. Earlier companion occurrences include 1971-266.3 and 1977-438.15.','this is the established derived-category construction; large categories require the usual universe or existence conventions.',[S,H],reconstruction='The size convention is stated to avoid assuming that arbitrary localization morphisms form sets.',literal='correct with missing hypotheses',area='Sheaves and homological algebra')
