def problem(pid,title,statement,occ,status,refs):
    problems.append(dict(id=pid,title=title,statement=statement,occurrences=occ,status='As of November 2026, '+status,status_date='2026-11',refs=refs))
    for x in items:
        if x['id'] in occ:x['problem']=pid

problem('GP-1987-01','Character realizations of Schubert polynomials',r'For each finite permutation \(w\), find a finite-dimensional polynomial representation, in a specified group category, whose torus character equals \(\mathfrak S_w\).',['1987-720.21'],r'the Borel-module formulation is solved by Kra\'skiewicz--Pragacz, in a 1986 preprint announced in 1987 and fully published in 2004. These modules need not be irreducible; the seminar does not specify a category for its stronger irreducibility wording. \citep[Theorem 4.1 and Introduction]{kraskiewiczpragacz2004schubert}',['kraskiewiczpragacz2004schubert'])
problem('GP-1987-02','Real and complex representability of a finite matroid',r'Given a finite matroid by its bases, determine whether it is representable over \(\mathbb R\) or over \(\mathbb C\).',['1985-658.13','1985-658.16','1987-725.3'],r'the finite decision problem is settled by polynomial encoding and quantifier elimination, available before 1987. The broader phrase classification is not made into a separate unresolved claim without a specified structural target. This is distinct from earlier problems on realization-space topology and determinant-sign isotopy. \citep[\S\S 2--3]{tarski1951decision}',['tarski1951decision'])
problem('GP-1987-03','Axiomatizing the nonzero-minor data of a bimatroid',r'Characterize abstract collections \(\mathcal R\) of equally sized row-column subset pairs by axioms generalizing nonzero square minors.',['1987-725.6'],r'the collection is a bimatroid exactly when \(\{(E\setminus I)\sqcup J:(I,J)\in\mathcal R\}\) is a matroid basis family on \(E\sqcup F\) containing \(E\). The checked modern exposition attributes the theory to Kung 1978. \citep[Proposition 2.2]{rohrleulirsch2026bimatroids}',['rohrleulirsch2026bimatroids','kung1978bimatroids'])
problem('GP-1987-04','Information in a bimatroid beyond its row and column matroids',r'Determine what data of a matrix bimatroid are lost when only its row matroid and column matroid are retained.',['1987-725.12'],r'the separate matroids do not determine the bimatroid; a two-by-two counterexample is given in the occurrence. Joint submatrix ranks, equivalently the nonzero square-minor pairs subject to bimatroid axioms, supply the missing data. \citep[Proposition 2.6]{rohrleulirsch2026bimatroids}',['rohrleulirsch2026bimatroids'])
problem('GP-1987-05','Generic irreducible Hecke characters in symmetric functions',r'For the semisimple type-A Hecke algebra \(H_N(q)\), give a symmetric-function formula for irreducible character values on standard cycle elements \(T_{w_\mu}\).',['1987-726.8'],r'a Frobenius formula is available; Ram published one in 1991, and Halverson--Ram give the exact normalization and credit several independent discoveries. This is a generic-parameter answer and does not settle the different root-of-unity decomposition problem. \citep[equation (4.10), Theorem 4.11]{halversonram1999bitraces}',['ram1991frobenius','halversonram1999bitraces'])

